import { writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { agentApiVersion, agentOperations,agentEventTransports } from '../src/agent-api/capabilities.ts';

type DocumentedOperation = Readonly<{
  id: string;
  method: string;
  path: string;
  scope?: string;
  requiredScopes?: readonly string[];
  description: string;
}>;

export function renderAgentOperations(operations: readonly DocumentedOperation[] = agentOperations): string {
  const lines = [
    '<!-- Generated by scripts/agent-skill-reference.ts. Update the registry and regenerate. -->',
    '',
    '# LifeOS Agent API operations',
    '',
    `Legacy catalog API version \`${agentApiVersion}\`; the v2 catalog uses API version \`2\` and requiredScopes arrays. Business paths retain their listed versions.`,
    '',
    'When enabled, the server MCP endpoint `/api/platform/mcp` exposes `lifeos_discover` and `lifeos_call` over the same API; there is no server `lifeos_retry`. Use only operations in both the current MCP discovery and this reviewed reference, within the user grant and the actual host qualification. An API row alone does not enable MCP access or write recovery.',
    '',
    'Read [the credential-runtime guide](credential-runtime.md) for server MCP versus durable-host recovery. Preserve target identity, original idempotency key, expectedRevision and independent GET readback across transports; never resend an uncertain write through a different transport.',
    '',
    '| ID | Method | Path | Required scopes | Purpose |',
    '| --- | --- | --- | --- | --- |',
    ...operations.map(({ id, method, path, scope, requiredScopes, description }) =>
      `| \`${id}\` | \`${method}\` | \`${path}\` | \`${requiredScopes?.length ? requiredScopes.join(', ') : scope ?? 'valid grant'}\` | ${description.replaceAll('|', '\\|').replace(/\r?\n/g, ' ')} |`),
    '',
    '## Native event transports — not JSON operations',
    '',
    '| ID | Transport | Method | Path | Required scopes |',
    '| --- | --- | --- | --- | --- |',
    ...agentEventTransports.map(operation=>`| \`${operation.id}\` | \`${operation.transport}\` | \`${operation.method}\` | \`${operation.path}\` | \`${operation.requiredScopes.join(', ')}\` |`),
    '',
  ];
  return lines.join('\n');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  writeFileSync(new URL('../skills/lifeos-agent/references/operations.md', import.meta.url), renderAgentOperations());
}
